function Modal({title,children,onClose,wide=false}:{title:string;children:ReactNode;onClose:()=>void;wide?:boolean}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{const d=ref.current;d?.showModal();return()=>d?.close();},[]);return <dialog ref={ref} className={'modal '+(wide?'wide':'')} onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal-heading"><h2>{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={21}/></button></div>{children}</dialog>;}
function Empty({icon:Icon=Bookmark,title,text,action}:{icon?:typeof Bookmark;title:string;text:string;action?:ReactNode}){return <div className="empty-state"><Icon size={35}/><h3>{title}</h3><p>{text}</p>{action}</div>;}

