 useEffect(()=>{if(!activityFocus)return;const timer=setTimeout(()=>{const el=document.getElementById(activityFocus);if(el){el.scrollIntoView({behavior:'smooth',block:'center'});el.focus({preventScroll:true});setActivityFocus('');}},150);return()=>clearTimeout(timer);},[activityFocus,view,journey]);
 async function journeyAction(payload:Record<string,unknown>,message?:string){if(busy)return null;if(!data.user){setEntered(false);return null;}setBusy(true);try{const r=await fetch('/api/journey',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json() as {error?:string;id?:string;ok?:boolean};if(!r.ok)throw new Error(d.error||'Please retry.');await refresh();if(message)setToast(message);return d;}catch(e){setToast(e instanceof Error?e.message:'Unable to save.');return null;}finally{setBusy(false);}}
 async function chatWith(designerId:string,context:string,itemId:string){const r=await journeyAction({action:'conversation',designerId,context,itemId});if(r?.id){setInitialConversation(r.id);await refreshInbox();setModal('');setSelected(null);navigate('messages');}}
 async function portalAction(payload:Record<string,unknown>,message?:string){if(busy)return null;if(!data.user){setModal('signin');return null;}setBusy(true);try{const r=await fetch('/api/portal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json() as {error?:string;id?:string;ok?:boolean};if(!r.ok)throw new Error(d.error);await refresh();if(message)setToast(message);return d;}catch(e){setToast(e instanceof Error?e.message:'Unable to save.');return null;}finally{setBusy(false);}}
 function enterPortal(role:PortalRole){if(!data.user)return;const url=new URL(window.location.href);url.searchParams.delete('portal');url.searchParams.delete('mode');window.history.replaceState({},'',url.pathname+url.search+url.hash);setPortalRole(role);setEntered(true);setSkipIntro(true);const profileId=new URLSearchParams(window.location.search).get('profile');if(profileId){setPublicProfile(profileId);navigate('profile');}else navigate(new URLSearchParams(window.location.search).has('post')?'feed':role==='creator'?'creator':role==='brand'?'brand':'foryou');}
