 useEffect(()=>{refresh();const handle=()=>{const h=window.location.hash.slice(1);const profileId=new URLSearchParams(window.location.search).get('profile');if(profileId)setPublicProfile(profileId);if(['wardrobe','projects','profile','foryou','style','measurements','lookbooks','requests','messages','materials','drops','commissions','feed','reels','marketplace','payments','discover','explore','shop','saved','liked','comments','studio','ai','creator','brand','orders','contact','account'].includes(h))setView(h);};handle();window.addEventListener('hashchange',handle);window.addEventListener('popstate',handle);return()=>{window.removeEventListener('hashchange',handle);window.removeEventListener('popstate',handle);};},[]);
 useEffect(()=>{
  let active=true,checking=false;
  const controller=new AbortController();
  async function checkSession(){
   if(checking||document.visibilityState!=='visible'||document.querySelector('dialog.account-dialog[open]'))return;
   checking=true;
   try{
    const response=await fetch('/api/session',{cache:'no-store',signal:controller.signal});
    if(!response.ok)return;
    const current=await response.json() as {user:{id:string}|null};
    if(active&&(current.user?.id||null)!==(data.user?.id||null)){
     setEntered(false);setSkipIntro(true);setLoading(true);setData(blank);setPortal(emptyPortal);setJourney(emptyJourney);setChatThreads([]);setUnread(0);await refresh();
    }
   }catch{}finally{checking=false;}
  }
  const timer=window.setInterval(checkSession,30000);
  window.addEventListener('focus',checkSession);document.addEventListener('visibilitychange',checkSession);
  return()=>{active=false;controller.abort();window.clearInterval(timer);window.removeEventListener('focus',checkSession);document.removeEventListener('visibilitychange',checkSession);};
 },[data.user?.id]);
