 async function saveDesign(publish:boolean,kind='creator'){const d=await mutate({action:'design',id:editId,title,description,category:designCategory,kind,published:publish,config},publish?'Design published to Explore.':'Design saved to your studio.');if(d){setEditId(d.id);setModal('');}}
 async function upload(file:File|undefined){if(!file)return;if(!data.user){setModal('signin');return;}if(file.size>5_000_000){setToast('Please choose an image under 5 MB.');return;}setBusy(true);try{const r=await fetch('/api/assets',{method:'POST',headers:{'Content-Type':file.type},body:file}),d=await r.json() as {error?:string;url:string};if(!r.ok)throw new Error(d.error);change({image:d.url,graphic:'none'});setToast('Artwork added. You can adjust its position and scale.');}catch(e){setToast(e instanceof Error?e.message:'Upload failed.');}finally{setBusy(false);}}
 async function exportDesign(){try{const source=document.getElementById('studio-garment') as unknown as SVGSVGElement|null;if(!source)return;const svg=source.cloneNode(true) as SVGSVGElement;svg.setAttribute('width','1600');svg.setAttribute('height','1680');for(const image of Array.from(svg.querySelectorAll('image'))){const href=image.getAttribute('href');if(href){const blob=await(await fetch(href)).blob();const url=await new Promise<string>((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(String(reader.result));reader.onerror=rej;reader.readAsDataURL(blob);});image.setAttribute('href',url);}}const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml;charset=utf-8'}));const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1680;canvas.getContext('2d')?.drawImage(img,0,0);canvas.toBlob(b=>{if(b){const download=URL.createObjectURL(b),a=document.createElement('a');a.href=download;a.download='sator-design-preview.png';a.click();setTimeout(()=>URL.revokeObjectURL(download),1000);}URL.revokeObjectURL(url);},'image/png');};img.onerror=()=>{URL.revokeObjectURL(url);setToast('Unable to export this design.');};img.src=url;}catch{setToast('Unable to export this design. Please retry.');}}
 function useRecipe(index:number){const r=recipes[index];setPast(p=>[...p,config]);setConfig({...config,color:r.color,ink:r.ink,graphic:r.graphic,text:r.text,subtext:r.subtext,image:''});setTitle(r.name);navigate('studio');setToast('Style recipe applied. Make it your own.');}
